




"use strict";

const InitFragment = require("../InitFragment");
const makeSerializable = require("../util/makeSerializable");
const { propertyAccess } = require("../util/property");
const {
	getConcatenatedExportAccess,
	handleDependencyBase
} = require("./CommonJsDependencyHelpers");
const NullDependency = require("./NullDependency");












const EMPTY_OBJECT = {};

class CommonJsExportsDependency extends NullDependency {
	






	constructor(range, valueRange, base, names) {
		super();
		this.range = range;
		this.valueRange = valueRange;
		
		this.base = base;
		
		this.names = names;
	}

	get type() {
		return "cjs exports";
	}

	




	getExports(moduleGraph) {
		const name = this.names[0];
		return {
			exports: [
				{
					name,
					
					
					
					canMangle: !(name in EMPTY_OBJECT)
				}
			],
			dependencies: undefined
		};
	}

	



	serialize(context) {
		context
			.write(this.range)
			.write(this.valueRange)
			.write(this.base)
			.write(this.names);
		super.serialize(context);
	}

	



	deserialize(context) {
		this.range = context.read();
		const c1 = context.rest;
		this.valueRange = c1.read();
		const c2 = c1.rest;
		this.base = c2.read();
		const c3 = c2.rest;
		this.names = c3.read();
		super.deserialize(c3.rest);
	}
}

makeSerializable(
	CommonJsExportsDependency,
	"webpack/lib/dependencies/CommonJsExportsDependency"
);

CommonJsExportsDependency.Template = class CommonJsExportsDependencyTemplate extends (
	NullDependency.Template
) {
	






	apply(
		dependency,
		source,
		{
			module,
			moduleGraph,
			initFragments,
			runtimeRequirements,
			runtime,
			concatenationScope
		}
	) {
		const dep =  (dependency);
		
		const used =  (
			moduleGraph.getExportsInfo(module).getUsedName(dep.names, runtime)
		);

		if (concatenationScope) {
			
			if (dep.base !== "exports" && dep.base !== "module.exports") {
				throw new Error(
					`Unsupported base ${dep.base} in concatenated CommonJS module`
				);
			}
			if (!used) {
				initFragments.push(
					new InitFragment(
						"var __webpack_unused_export__;\n",
						InitFragment.STAGE_CONSTANTS,
						0,
						"__webpack_unused_export__"
					)
				);
				source.replace(
					dep.range[0],
					dep.range[1] - 1,
					"__webpack_unused_export__"
				);
				return;
			}
			source.replace(
				dep.range[0],
				dep.range[1] - 1,
				getConcatenatedExportAccess(
					concatenationScope,
					initFragments,
					dep.names
				)
			);
			return;
		}

		const [type, base] = handleDependencyBase(
			dep.base,
			module,
			runtimeRequirements
		);

		switch (type) {
			case "expression":
				if (!used) {
					initFragments.push(
						new InitFragment(
							"var __webpack_unused_export__;\n",
							InitFragment.STAGE_CONSTANTS,
							0,
							"__webpack_unused_export__"
						)
					);
					source.replace(
						dep.range[0],
						dep.range[1] - 1,
						"__webpack_unused_export__"
					);
					return;
				}
				source.replace(
					dep.range[0],
					dep.range[1] - 1,
					`${base}${propertyAccess( (used))}`
				);
				return;
			case "Object.defineProperty":
				if (!used) {
					initFragments.push(
						new InitFragment(
							"var __webpack_unused_export__;\n",
							InitFragment.STAGE_CONSTANTS,
							0,
							"__webpack_unused_export__"
						)
					);
					source.replace(
						dep.range[0],
						 (dep.valueRange)[0] - 1,
						"__webpack_unused_export__ = ("
					);
					source.replace(
						 (dep.valueRange)[1],
						dep.range[1] - 1,
						")"
					);
					return;
				}
				source.replace(
					dep.range[0],
					 (dep.valueRange)[0] - 1,
					`Object.defineProperty(${base}${propertyAccess(
						 (used).slice(0, -1)
					)}, ${JSON.stringify(used[used.length - 1])}, (`
				);
				source.replace(
					 (dep.valueRange)[1],
					dep.range[1] - 1,
					"))"
				);
		}
	}
};

module.exports = CommonJsExportsDependency;
